namespace kstation {
// CPU-independent K clock graph, under the verified even/on-chip frame timing
// contract. Fixed-capacity typed continuations own all internal child calls.
class ControllerClockRuntime final {
 using T=ClockTickTask;using P=ClockPulseTask;using R=ClockReadTask;using W=ClockSendTask;using Frame=std::variant<std::monostate,T,P,R,W>;
public:
 enum class Block:uint8_t{None,Inactive,Interrupt,UnsupportedMode,Capacity};struct Result{unsigned clocks=0;bool returned=false;Block blocked=Block::None;};
 bool active()const{return depth_!=0;}unsigned depth()const{return depth_;}void reset(){for(auto&f:frames_)f.emplace<std::monostate>();depth_=0;}bool startLatched(){if(active())return false;frames_[depth_++].emplace<P>(P::Kind::Latched,0,0);return true;}bool startTick(){if(active())return false;frames_[depth_++].emplace<T>();return true;}
 Result advanceBefore(ControllerDeviceState&d,unsigned available,bool interruptsEnabled=false){if(!active())return {0,false,Block::Inactive};if(d.interruptMode2||d.pendingIrqsHigh)return {0,false,Block::UnsupportedMode};if(d.pendingIrqs&&interruptsEnabled)return {0,false,Block::Interrupt};ClockCredits c{};auto writeCredit=[&](uint32_t a){int prev=d.lastWrite;if(a<0x400000||(a>=0xfffd10&&a<0xffffa0))return ((prev&1)||a!=uint32_t(prev|1))?(a<0x400000?3u:1u):0u;return a>=0xffffa0?1u:3u;};c.flagWrite=writeCredit(0xfffe6f);c.latchWrite=writeCredit(0xfffe73);P::Credits pc{c.call,c.shortCall,c.ret,c.retainWord,c.restoreWord,c.flagWrite};auto&f=frames_[depth_-1];bool stackWrite=false;if(auto*t=std::get_if<T>(&f))stackWrite=t->stage()==T::Stage::RetainIncrement||t->stage()==T::Stage::RetainCount||t->stage()==T::Stage::SendClock;else if(auto*p=std::get_if<P>(&f))stackWrite=p->stage()==P::Stage::ConsumeLatched||p->stage()==P::Stage::ReadResetTick||p->stage()==P::Stage::ReadTick||p->stage()==P::Stage::RetainAverage;else if(auto*w=std::get_if<W>(&f))stackWrite=w->stage()==W::Stage::RetainValue;unsigned cost=std::visit([&](const auto&t)->unsigned{using Q=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<Q,std::monostate>)return 0;else if constexpr(std::is_same_v<Q,P>)return t.nextClocks(pc);else return t.nextClocks(c);},f);const unsigned arb=d.pendingIrqs?1:0;if(!cost||available<cost+arb)return {};if(arb)(void)d.read8(0xfffff2);const auto begin=d.cycles;
  auto history=[](uint32_t a){return a<0x400000||(a>=0xfffd10&&a<0xffffa0)?int(a):-1;};
  auto rb=[&](uint32_t a,unsigned off){d.cycles=begin+off;d.lastRead=history(a);return d.readResource(a);};auto wb=[&](uint32_t a,uint8_t v,unsigned off){d.cycles=begin+off;d.lastWrite=history(a);d.writeResource(a,v);};
  auto read=[&](uint32_t a,unsigned width,unsigned end)->uint32_t{uint32_t value=0;for(unsigned i=0;i<width;++i){unsigned off=end;if(width==4&&i<2)--off;value=(value<<8)|rb(a+i,off);}return value;};
  auto write=[&](uint32_t a,uint32_t v,unsigned width,unsigned end){for(unsigned i=0;i<width;++i){unsigned off=end;if(width==4&&i<2)--off;wb(a+i,uint8_t(v>>(8*(width-i-1))),off);}};
  unsigned used=0;bool dispatch=false;P::Stage pulseResume=P::Stage::Complete;uint8_t source=0;
  if(auto*t=std::get_if<T>(&f)){used=t->advanceBefore(cost,c,[&](T::Read r)->uint32_t{switch(r){case T::Read::Increment:return read(0xfffe56,4,cost);case T::Read::Phase:return read(0xfffe52,4,cost);case T::Read::PulseCount:return read(0xfffe50,2,cost);case T::Read::OutputFlags:return read(0xfffe6f,1,cost);case T::Read::Secondary:return read(0xfffe5a,4,cost);case T::Read::SecondaryIncrement:return read(0xfffe5e,4,cost);case T::Read::RunFlags:return read(0xfffe6f,1,cost);case T::Read::Timeout:return read(0xfffe72,1,cost);}return 0;},[&](T::Write w,uint32_t v){switch(w){case T::Write::Phase:write(0xfffe52,v,4,cost);break;case T::Write::PulseCount:write(0xfffe50,v,2,cost);break;case T::Write::Secondary:write(0xfffe5a,v,4,cost);break;case T::Write::Timeout:write(0xfffe72,v,1,cost);break;case T::Write::RunFlags:write(0xfffe6f,v,1,cost);break;}});dispatch=t->awaitingChild();}
  else if(auto*p=std::get_if<P>(&f)){auto stage=p->stage();used=p->advanceBefore(cost,pc,[&](P::Read r)->uint32_t{switch(r){case P::Read::Latched:return read(0xfffe72,1,cost);case P::Read::Flags:return read(0xfffe6f,1,stage==P::Stage::WriteSourceFlag?7:cost);case P::Read::Active:return read(0xfffe6e,1,cost);case P::Read::Pulses:return read(0xfffe50,2,cost);case P::Read::PulseCount:return read(0xfffe80,2,cost);case P::Read::Timer:return read(0xfffe50,4,cost);case P::Read::Sum:return read(0xfffe82,4,cost);case P::Read::Samples:return read(0xfffe74,2,cost);case P::Read::PreviousTick:return read(0xfffe76,2,cost);case P::Read::Estimate:return read(0xfffe78,4,cost);case P::Read::Gain:return read(0xfffe7c,2,cost);case P::Read::Integral:return read(0xfffe7e,2,cost);}return 0;},[&](P::Write w,uint32_t v){switch(w){case P::Write::Latched:write(0xfffe72,v,1,cost);break;case P::Write::Flags:write(0xfffe6f,v,1,cost);break;case P::Write::PreviousTick:write(0xfffe76,v,2,cost);break;case P::Write::Samples:write(0xfffe74,v,2,cost);break;case P::Write::Sum:write(0xfffe82,v,4,cost);break;case P::Write::PulseCount:write(0xfffe80,v,2,cost);break;case P::Write::SumHigh:write(0xfffe82,v,2,cost);break;case P::Write::SumLow:write(0xfffe84,v,2,cost);break;case P::Write::Estimate:write(0xfffe78,v,4,cost);break;case P::Write::Period:write(0xfffe56,v,4,cost);break;case P::Write::Integral:write(0xfffe7e,v,2,cost);break;case P::Write::Gain:write(0xfffe7c,v,2,cost);break;}});dispatch=p->awaitingChild();pulseResume=p->resumeStage();source=p->source();}
  else if(auto*r=std::get_if<R>(&f))used=r->advanceBefore(cost,c,[&](R::Read field)->uint32_t{if(field==R::Read::Counter)return read(0xffff86,2,cost);if(field==R::Read::Overflow)return read(0xfffd28,2,cost);return read(0xffff85,1,cost);});
  else if(auto*w=std::get_if<W>(&f))used=w->advanceBefore(cost,c,[&](W::Write field,uint32_t v){write(field==W::Write::Latch?0xfffe73:0xffffb2,v,1,cost);});
  if(used!=cost)return {};d.cycles=begin+cost;d.lastRead=-1;if(stackWrite)d.lastWrite=-1;
  bool done=std::visit([](const auto&t){using Q=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<Q,std::monostate>)return false;else return t.complete();},f);
  if(done){uint16_t value=0;if(auto*r=std::get_if<R>(&f))value=r->result();f.emplace<std::monostate>();--depth_;if(depth_){auto&parent=frames_[depth_-1];if(auto*t=std::get_if<T>(&parent))t->resumeChild();else if(auto*p=std::get_if<P>(&parent))p->resumeChild(value);}return {cost+arb,depth_==0,Block::None};}
  if(dispatch){if(depth_==frames_.size())return {cost+arb,false,Block::Capacity};if(std::holds_alternative<T>(f))frames_[depth_++].emplace<W>();else if(pulseResume==P::Stage::ClearLatched)frames_[depth_++].emplace<P>(P::Kind::Edge,0,source);else frames_[depth_++].emplace<R>();}
  return {cost+arb,false,Block::None};
 }
private:std::array<Frame,8>frames_{};unsigned depth_=0;
};
}
